    const N = 8;
    const at = (i) => {
      const t = i / (N - 1);
      return 'left:' + (10 + t * 80).toFixed(1) + '%;bottom:calc(15% + ' + (4 * t * (1 - t) * 58).toFixed(1) + '%)';
